  const findHierarchyById = (data: any, id: any) => {
    let result = null;

    const search: any = (nodes: any) => {
      for (const node of nodes) {
        if (node.ID === id) {
          return node;
        }
        if (node?.childs && node.childs.length > 0) {
          const found = search(node.childs);
          if (found) {
            return { ...node, childs: [found] };
          }
        }
      }
      return null;
    };

    result = search(data);

    return result ? result : [];
  };

