    data.forEach((val: any) => {
      // Check if the current item matches the condition
      if (val.Id === item?.ParentID && item?.ParentID !== 0) {
        result.push(val);
      }

      // Recursively check in child arrays if they exist
      if (val.childs && val.childs.length > 0) {
        findMatchingItems(val.childs, item, result);
      }
    });
  }
