import * as React from "react";
import { useEffect, useState } from 'react';
import pnp, { Web } from "sp-pnp-js";
import "@pnp/sp/sputilities";
import * as moment from 'moment';
import { SPFI, SPFx as spSPFx } from "@pnp/sp";
import { GlobalConstants } from '../globalComponents/LocalCommon';
import { PageContext } from "@microsoft/sp-page-context";
import { spfi } from "@pnp/sp/presets/all";
import { MSGraphClientV3 } from '@microsoft/sp-http';
import { DynamicAlert } from "./DynamicAlert";
import { IDBPDatabase, openDB } from 'idb';
import pako from 'pako';
import { createWorker } from "../globalComponents/WebWorker";
import { devError, devSuccess } from "../common/Utils";
import { Toast, ToastTitle } from "@fluentui/react-components";
export const myContextValue: any = React.createContext<any>({})
import { HttpClient, HttpClientResponse } from '@microsoft/sp-http';
//import AllModifiedData from "./AllModifiedData";

export const updateBackendLanguageSelection = async (url: string, smartMetadataListID: string, selectedLang: any, supportedLanguages: any) => {
    try {
        let web = new Web(url);
        // Get all language items
        // Update all languages: set IsSelected to true for selected language, false for others
        const updatePromises = supportedLanguages?.map((lang: any) => {
            const isSelected = lang.Id === selectedLang.Id;
            return web.lists.getById(smartMetadataListID)
                .items.getById(lang.Id)
                .update({ IsSelected: isSelected });
        });
        await Promise.all(updatePromises);
        // Dispatch custom event for language change
        const event = new CustomEvent('languageChange', { detail: { selectedLanguage: selectedLang.Title } });
        window.dispatchEvent(event);
    } catch (error) {
        return Promise.reject(error);
    }
};


export const isMultilungalSupported = async (siteUrl:string,SmartMetadataListID:string) => {
    let supportedLanguagesSelected: any = [];
    let result: false;
    try {
      let web = new Web(siteUrl);
      await web.lists.getByTitle('AdminConfigurations').items.select("Title", "Id", "Value", "Key", "Configurations", "IsMultiLanguage").filter("Key eq 'MultiLanguageConfig'").orderBy("Created", false).getAll().then(async (data: any) => {
        if (data?.length != undefined && data?.length > 0) {
          result = data[0]?.IsMultiLanguage;
        }
      }).catch((err: any) => {
        devError(err, "Oops! Something went wrong.");
      });
    } catch (error) {
      devError(error, "Oops! Something went wrong.");
    }


    try {
      if (result) {
        let web = new Web(siteUrl);
        let publicData: any = await web.lists.getById(SmartMetadataListID).items.select('PageTitle', 'Id', 'Status', 'TaxType', 'IsSelected', 'Title').filter(`TaxType eq 'Language'`).get();
        if (publicData?.length != undefined && publicData?.length > 0) {
          return {supportedLanguagesSelected: publicData, result};
        }
        return {supportedLanguagesSelected, result};
      }
      else {
        return {supportedLanguagesSelected, result};
      }
    } catch (error) {
      devError(error, "Oops! Something went wrong.");;
    }
  }

export const pageContext = async () => {
    let result;
    try {
        result = (await pnp.sp.site.getContextInfo());
    }
    catch (error) {
        return Promise.reject(error);
    }

    return result;

}
export const docxUint8Array = async () => {
    let result: any = [];
    await getData('https://hhhhteams.sharepoint.com/sites/HHHH/SP', 'e968902a-3021-4af2-a30a-174ea95cf8fa', "Id,ID,Title,Configurations&$filter=Title eq 'docxConfig'").then((data: any) => {
        const regularArray = JSON.parse(data[0].Configurations);
        const uint8Array = new Uint8Array(regularArray).buffer;
        result = uint8Array;
    })
    return result
}
export const findTaskCategoryParent = (taskCategories: any, result: any) => {
    if (taskCategories?.length > 0 && result.TaskCategories?.length > 0) {
        let newTaskCat = taskCategories?.filter((val: any) => result?.TaskCategories?.some((elem: any) => val.Id === elem.Id));
        newTaskCat.map((elemVal: any) => {
            if (result[elemVal?.Parent?.Title]) {
                result[elemVal?.Parent?.Title] += ` ${elemVal?.Title}`
            } else {
                result[elemVal?.Parent?.Title] = elemVal?.Title;
            }
        })
    }
    return result;

