import { getSPUsers, getSPAssetFamilies, getSPAssets, getSPRequests, getSPVendors, createAssetProfile, createAsset, updateAsset, createRequest, updateRequestStatus, fulfillRequest, buildFulfilledAssetUpdate, updateUserProfileImageWithAttachment, updateSPUser, deleteSPItem, bulkCreateAssets, updateAssetProfile, createSPUser, getPlatformAccounts, createPlatformAccount, updatePlatformAccount, deletePlatformAccount, getInternalLicenses, getSubscribedSkus, formatDateDDMMYYYY, formatMetadataDate, getSPRequestById, getSPListId, isRenewalDateExpired, processAutoRenewals, getAssignedUserCount, hasAssignmentCapacity, normalizeAssetExpiryDates, createConcern, addConcernReply, closeConcern, reopenConcern, getConcernStatusLabel, getConcernAssetName, isConcernOpen } from './services/sharepointDataMapper';
import FulfillRequestModal from './components/FulfillRequestModal';
