import { DynamicAlert } from '../../globalComponents/DynamicAlert';
import Tooltip from '../../globalComponents/Tooltip';


type View = 'dashboard' | 'licenses' | 'hardware' | 'users' | 'requests' | 'concerns' | 'reports' | 'admin';
type ModalMode = 'family' | 'instance';
type RequestType = 'license' | 'hardware';
type RouteFilter = 'all' | 'expiring' | 'active' | 'pending' | 'open';

/** Parsed application route from the current page query string. */
interface AppRouteState {
    view: View;
    userId: string | null;
    familyId: string | null;
    assetTitle: string | null;
    mode: 'families' | 'items';
    filter: RouteFilter;
}

const VALID_VIEWS: View[] = ['dashboard', 'licenses', 'hardware', 'users', 'requests', 'concerns', 'reports', 'admin'];

const parseViewParam = (params: URLSearchParams): View => {
    const raw = (params.get('view') || params.get('tab') || 'dashboard').toLowerCase();
    return VALID_VIEWS.indexOf(raw as View) !== -1 ? (raw as View) : 'dashboard';
};

const parseRouteFilter = (params: URLSearchParams): RouteFilter => {
    const raw = params.get('filter');
    if (raw === 'expiring' || raw === 'active' || raw === 'pending' || raw === 'open') {
        return raw;
    }
    return 'all';
};

/** Read the current SharePoint page URL into an in-app route object. */
const parseRouteFromUrl = (): AppRouteState => {
    const params = new URLSearchParams(window.location.search);
    const familyId = params.get('familyId') || params.get('assetId') || null;
    return {
        view: parseViewParam(params),
        userId: params.get('userId'),
        familyId,
        assetTitle: params.get('assetTitle'),
        mode: params.get('mode') === 'families' ? 'families' : 'items',
        filter: parseRouteFilter(params),
    };
};

/** Build a query string from in-app navigation state (omits default values). */
const buildRouteSearch = (route: AppRouteState): string => {
    const params = new URLSearchParams();
    if (route.view !== 'dashboard') params.set('view', route.view);
    if (route.userId) params.set('userId', route.userId);
    if (route.familyId) {
        params.set('familyId', route.familyId);
        // Keep assetId in sync for legacy deep-links from staticDashboard / assetProfile.
        params.set('assetId', route.familyId);
    } else if (route.assetTitle) {
        params.set('assetTitle', route.assetTitle);
    }
    if (route.mode === 'families') params.set('mode', 'families');
    if (route.filter !== 'all') params.set('filter', route.filter);
    return params.toString();
};

/** Push or replace the browser URL to reflect the current in-app route. */
const applyRouteToUrl = (route: AppRouteState, replace = true) => {
    const search = buildRouteSearch(route);
    const nextUrl = search
        ? `${window.location.pathname}?${search}`
        : window.location.pathname;
    const currentUrl = `${window.location.pathname}${window.location.search}`;
    if (nextUrl === currentUrl) return;
    if (replace) {
        window.history.replaceState({ teamMgmtRoute: route }, '', nextUrl);
    } else {
        window.history.pushState({ teamMgmtRoute: route }, '', nextUrl);
    }
};

const initialAppRoute = parseRouteFromUrl();

const StatCard: React.FC<{ icon: React.ElementType, title: string, value: string | number, color: string, subtext?: string, onClick?: () => void }> = ({ icon: Icon, title, value, color, subtext, onClick }) => (
    <div
        onClick={onClick}
        className={`card shadow-sm border h-100 ${onClick ? 'cursor-pointer' : ''}`}
        style={{ transition: 'all 0.2s' }}
    >
