const renderContent = () => {
    // If a user is selected (Drill down mode)
    if (selectedUser) {
        // Filter assets for this specific selected user
        const userAssets = assets.filter(asset =>
            (asset.assignedUser?.id === selectedUser.id) ||
            (asset.assignedUsers?.some(u => u.id === selectedUser.id))
        );
        return (
            <div className="container-fluid p-0">
                <button onClick={handleBackToList} className="btn btn-outline-secondary btn-sm mb-4"> &larr; Back to List </button>
                <UserProfile
                    user={selectedUser}
                    userAssets={userAssets}
                    assetFamilies={assetFamilies}
                    config={config}
                    onEditProfile={() => {
                        if (selectedUser) {
                            setUserForModal(selectedUser);
                            setIsProfileModalOpen(true);
                        }
                    }}
                    onNewRequest={handleNewRequest}
                    onQuickRequest={handleQuickRequest}
                    onUpdateUser={handleSaveUser}
                    onSavePlatformAccount={(account) => {
                        if (selectedUser) handleSavePlatformAccount(account, selectedUser.id.toString());
                    }}
                    onDeletePlatformAccount={(accountId) => {
                        if (selectedUser) handleDeletePlatformAccount(accountId, selectedUser.id.toString());
                    }}
                    AllListId={AllListId}
                />
            </div>
        );
    }

    // Family Detail View
    if (selectedFamilyId && isAdmin) {
        const family = assetFamilies.find(f => f.id === selectedFamilyId);
        if (!family) return <div>Family not found</div>;
        return (
            <AssetProfile
                family={family}
                allAssets={assets}
                onBack={handleBackToList}
                onEditAsset={handleEditAsset}
                onUserClick={handleUserClick}
                onAddInstance={handleAddInstance}
                onEditFamily={handleEditFamily}
                onBulkCreate={handleBulkCreate}
                AllListId={AllListId}
            />
        );
    }

    // Main Views
    switch (activeView) {
        case 'dashboard': return (
            <div className="container-fluid p-0">
                {isAdmin ? (
                    <div className="d-grid gap-4">
                        {/* Admin Header Stats */}
                        <div className="d-flex flex-nowrap gap-4" style={{ overflowX: 'auto' }}>
                            <div className="flex-grow-1" style={{ minWidth: 0 }}><StatCard icon={Users} title="Total Team" value={dashboardStats.totalUsers!} color="#4f46e5" subtext="All Members" onClick={() => handleNavigation('users')} /></div>
                            <div className="flex-grow-1" style={{ minWidth: 0 }}><StatCard icon={UserIcon} title="Active Users" value={dashboardStats.activeUsersCount!} color="#22c55e" subtext="Currently Active" onClick={() => handleNavigation('users', 'active')} /></div>
                            <div className="flex-grow-1" style={{ minWidth: 0 }}><StatCard icon={Package} title="Assets Managed" value={dashboardStats.total!} color="#10b981" subtext="Hardware & Licenses" onClick={() => handleNavigation('licenses')} /></div>
                            <div className="flex-grow-1" style={{ minWidth: 0 }}><StatCard icon={ShieldAlert} title="Pending Actions" value={dashboardStats.pendingRequests!} color="#f59e0b" subtext="Requests needing approval" onClick={() => handleNavigation('requests', 'pending')} /></div>
                            <div className="flex-grow-1" style={{ minWidth: 0 }}><StatCard icon={MessageSquare} title="Open Concerns" value={dashboardStats.openConcerns!} color="#6366f1" subtext="Employee issues to resolve" onClick={() => handleNavigation('concerns', 'open')} /></div>

